const d = @import("dataset.zig");
pub const Center = struct { value: f64, fraction: f64 };
pub const Status = enum { ok, high, low };
pub const Point = struct { value: f64, lcl: f64, ucl: f64, z: f64, status: Status };
pub fn centerline(chart: usize, lots: []const d.Lot, numbers: []const usize) Center {
    var defective: i64 = 0; var defects: i64 = 0; var inspected: i64 = 0;
    for (numbers) |number| { const lot = lots[number - 1]; defective += lot.defectives; defects += lot.defects; inspected += lot.inspected; }
    return .{ .value = switch (chart) { 0 => d.real(defective) / d.real(inspected), 1 => d.real(defective) / d.real(numbers.len), 2 => d.real(defects) / d.real(numbers.len), else => d.real(defects) / d.real(inspected) }, .fraction = d.real(defective) / d.real(inspected) };
}
pub fn point(chart: usize, lot: d.Lot, center: Center) Point {
    const cl = center.value;
    const value = switch (chart) { 0 => d.real(lot.defectives) / d.real(lot.inspected), 1 => d.real(lot.defectives), 2 => d.real(lot.defects), else => d.real(lot.defects) / d.real(lot.inspected) };
    const sigma = @sqrt(switch (chart) { 0 => cl * (1 - cl) / d.real(lot.inspected), 1 => cl * (1 - center.fraction), 2 => cl, else => cl / d.real(lot.inspected) });
    const lcl = @max(0, cl - 3 * sigma);
    const ucl = cl + 3 * sigma;
    return .{ .value = value, .lcl = lcl, .ucl = ucl, .z = (value - cl) / sigma, .status = if (value > ucl) .high else if (value < lcl) .low else .ok };
}

const std = @import("std");
const d = @import("dataset.zig");
const v = @import("variable_charts.zig");
pub const Result = struct { count: usize, mean: f64, sigma_within: f64, sigma_sbar: f64, sigma_overall: f64, cp: f64, cpu: f64, cpl: f64, cpk: f64, pp: f64, ppu: f64, ppl: f64, ppk: f64, cpm: f64, cpk_ci: [2]f64, ppk_ci: [2]f64, below: usize, above: usize, ppm: f64, verdict: []const u8 };
fn indices(mean: f64, sigma: f64, s: d.Settings) [4]f64 { const upper = (d.real(s.usl) - mean) / (3 * sigma); const lower = (mean - d.real(s.lsl)) / (3 * sigma); return .{ d.real(s.usl - s.lsl) / (6 * sigma), upper, lower, @min(upper, lower) }; }
fn interval(value: f64, count: usize, z: f64) [2]f64 { const delta = z * @sqrt(1 / d.real(9 * count) + value * value / d.real(2 * (count - 1))); return .{ value - delta, value + delta }; }
pub fn assess(groups: []const v.Subgroup, numbers: []const usize, s: d.Settings, c: d.Constants) Result {
    var total: i64 = 0; var ranges: i64 = 0; var deviations: f64 = 0;
    for (numbers) |number| { const g = groups[number - 1]; total += g.total; ranges += g.range; deviations += g.sd; }
    const count = numbers.len * s.n;
    const mean = d.real(total) / d.real(count);
    const within = (d.real(ranges) / d.real(numbers.len)) / c.d2;
    const sbar = (deviations / d.real(numbers.len)) / c.c4;
    var squares: f64 = 0; var below: usize = 0; var above: usize = 0;
    for (numbers) |number| for (groups[number - 1].values) |value| { const delta = d.real(value) - mean; squares += delta * delta; if (value < s.lsl) below += 1; if (value > s.usl) above += 1; };
    const overall = @sqrt(squares / d.real(count - 1));
    const cp = indices(mean, within, s); const pp = indices(mean, overall, s); const offset = mean - d.real(s.target);
    return .{ .count = count, .mean = mean, .sigma_within = within, .sigma_sbar = sbar, .sigma_overall = overall, .cp = cp[0], .cpu = cp[1], .cpl = cp[2], .cpk = cp[3], .pp = pp[0], .ppu = pp[1], .ppl = pp[2], .ppk = pp[3], .cpm = d.real(s.usl - s.lsl) / (6 * @sqrt(overall * overall + offset * offset)), .cpk_ci = interval(cp[3], count, s.z), .ppk_ci = interval(pp[3], count, s.z), .below = below, .above = above, .ppm = d.real(1000000 * (below + above)) / d.real(count), .verdict = if (cp[3] >= 1.33) "capable" else if (cp[3] >= 1) "marginal" else "incapable" };
}
pub fn histogram(groups: []const v.Subgroup, numbers: []const usize, s: d.Settings) d.Strings {
    var low = s.lsl; var high = s.usl;
    for (numbers) |number| for (groups[number - 1].values) |value| { low = @min(low, value); high = @max(high, value); };
    low = s.bin * @divFloor(low, s.bin); high = s.bin * @divFloor(high, s.bin) + s.bin;
    const frequencies = d.alloc(usize, @intCast(@divFloor(high - low, s.bin))); @memset(frequencies, 0);
    for (numbers) |number| for (groups[number - 1].values) |value| { frequencies[@intCast(@divFloor(value - low, s.bin))] += 1; };
    var top: usize = 0; for (frequencies) |frequency| top = @max(top, frequency);
    var rows: std.ArrayList([]const u8) = .empty;
    for (frequencies, 0..) |frequency, i| {
        const a = low + @as(i64, @intCast(i)) * s.bin; const b = a + s.bin - 1;
        var parts: std.ArrayList([]const u8) = .empty;
        d.append([]const u8, &parts, d.fmt("bin {d} {d} {d}", .{ a, b, frequency }));
        if (frequency > 0) d.append([]const u8, &parts, d.repeated('#', (50 * frequency + top - 1) / top));
        const names = [_][]const u8{ "lsl", "target", "usl" }; const marks = [_]i64{ s.lsl, s.target, s.usl };
        for (names, marks) |name, value| { if (value >= a and value <= b) d.append([]const u8, &parts, name); }
        d.append([]const u8, &rows, d.join(parts.items, " "));
    }
    return rows.items;
}

const std = @import("std");
pub var allocator: std.mem.Allocator = undefined;
pub const Strings = []const []const u8;
pub fn eq(a: []const u8, b: []const u8) bool { return std.mem.eql(u8, a, b); }
pub fn alloc(comptime T: type, count: usize) []T { return allocator.alloc(T, count) catch @panic("allocation failed"); }
pub fn clone(comptime T: type, values: []const T) []T { return allocator.dupe(T, values) catch @panic("allocation failed"); }
pub fn append(comptime T: type, list: *std.ArrayList(T), value: T) void { list.append(allocator, value) catch @panic("allocation failed"); }
pub fn fmt(comptime pattern: []const u8, args: anytype) []const u8 { return std.fmt.allocPrint(allocator, pattern, args) catch @panic("allocation failed"); }
pub fn join(parts: Strings, separator: []const u8) []const u8 { return std.mem.join(allocator, separator, parts) catch @panic("allocation failed"); }
pub fn split(text: []const u8, delimiter: u8) Strings { var parts: std.ArrayList([]const u8) = .empty; var it = std.mem.splitScalar(u8, text, delimiter); while (it.next()) |part| append([]const u8, &parts, part); return parts.items; }
pub fn lines(text: []const u8) Strings { const parts = split(text, '\n'); return parts[0..parts.len - 1]; }
pub fn integer(text: []const u8) i64 { return std.fmt.parseInt(i64, text, 10) catch unreachable; }
pub fn natural(text: []const u8) usize { return @intCast(integer(text)); }
pub fn real(value: anytype) f64 { return @floatFromInt(value); }
pub fn number(text: []const u8) f64 { return std.fmt.parseFloat(f64, text) catch unreachable; }
pub fn repeated(byte: u8, count: usize) []const u8 { const text = alloc(u8, count); @memset(text, byte); return text; }
pub fn sequence(first: usize, last: usize) []usize { const result = alloc(usize, if (last >= first) last - first + 1 else 0); for (result, first..) |*value, i| value.* = i; return result; }
pub fn contains(numbers: []const usize, value: usize) bool { return std.mem.findScalar(usize, numbers, value) != null; }
pub const Settings = struct { characteristic: []const u8, lsl: i64, usl: i64, target: i64, n: usize, m: usize, passes: usize, rules: [7][]const usize, k: f64, h: f64, lambda: f64, e: f64, span: usize, gap: usize, z: f64, bin: i64, window: usize, step: usize };
pub const Lot = struct { number: usize, inspected: i64, defectives: i64, defects: i64 };
pub const Constants = struct { a2: f64, a3: f64, b3: f64, b4: f64, d3: f64, d4: f64, d2: f64, c4: f64 };
pub fn constants(n: usize) Constants {
    const rows: [9][8]f64 = .{
        .{ 1.880, 2.659, 0, 3.267, 0, 3.267, 1.128, 0.7979 },
        .{ 1.023, 1.954, 0, 2.568, 0, 2.574, 1.693, 0.8862 },
        .{ 0.729, 1.628, 0, 2.266, 0, 2.282, 2.059, 0.9213 },
        .{ 0.577, 1.427, 0, 2.089, 0, 2.114, 2.326, 0.9400 },
        .{ 0.483, 1.287, 0.030, 1.970, 0, 2.004, 2.534, 0.9515 },
        .{ 0.419, 1.182, 0.118, 1.882, 0.076, 1.924, 2.704, 0.9594 },
        .{ 0.373, 1.099, 0.185, 1.815, 0.136, 1.864, 2.847, 0.9650 },
        .{ 0.337, 1.032, 0.239, 1.761, 0.184, 1.816, 2.970, 0.9693 },
        .{ 0.308, 0.975, 0.284, 1.716, 0.223, 1.777, 3.078, 0.9727 },
    };
    const r = rows[n - 2];
    return .{ .a2 = r[0], .a3 = r[1], .b3 = r[2], .b4 = r[3], .d3 = r[4], .d4 = r[5], .d2 = r[6], .c4 = r[7] };
}
pub fn settings(text: []const u8) Settings {
    var result: Settings = undefined;
    var rule: usize = 0;
    for (lines(text)) |line| {
        const f = split(line, ' ');
        if (eq(f[0], "rules")) { const values = alloc(usize, f.len - 2); for (f[2..], values) |field, *value| value.* = natural(field); result.rules[rule] = values; rule += 1; }
        else if (eq(f[0], "characteristic")) result.characteristic = f[1]
        else if (eq(f[0], "lsl")) result.lsl = integer(f[1])
        else if (eq(f[0], "usl")) result.usl = integer(f[1])
        else if (eq(f[0], "target")) result.target = integer(f[1])
        else if (eq(f[0], "subgroup_size")) result.n = natural(f[1])
        else if (eq(f[0], "phase1_subgroups")) result.m = natural(f[1])
        else if (eq(f[0], "max_passes")) result.passes = natural(f[1])
        else if (eq(f[0], "cusum_k")) result.k = number(f[1])
        else if (eq(f[0], "cusum_h")) result.h = number(f[1])
        else if (eq(f[0], "ewma_lambda")) result.lambda = number(f[1])
        else if (eq(f[0], "ewma_l")) result.e = number(f[1])
        else if (eq(f[0], "ma_span")) result.span = natural(f[1])
        else if (eq(f[0], "event_gap")) result.gap = natural(f[1])
        else if (eq(f[0], "ci_z")) result.z = number(f[1])
        else if (eq(f[0], "histogram_bin")) result.bin = integer(f[1])
        else if (eq(f[0], "rolling_window")) result.window = natural(f[1])
        else if (eq(f[0], "rolling_step")) result.step = natural(f[1]);
    }
    return result;
}
pub fn measurements(text: []const u8) []const i64 { var result: std.ArrayList(i64) = .empty; for (lines(text)[1..]) |line| append(i64, &result, integer(split(line, ',')[2])); return result.items; }
pub fn attributes(text: []const u8) []const Lot { var result: std.ArrayList(Lot) = .empty; for (lines(text)[1..]) |line| { const f = split(line, ','); append(Lot, &result, .{ .number = natural(f[0]), .inspected = integer(f[1]), .defectives = integer(f[2]), .defects = integer(f[3]) }); } return result.items; }

const std = @import("std");
const d = @import("dataset.zig");
const v = @import("variable_charts.zig");
const attr = @import("attribute_charts.zig");
const rules = @import("run_rules.zig");
const cap = @import("capability.zig");
const plot = @import("plot.zig");
const charts = [_][]const u8{ "XBAR_R", "R", "XBAR_S", "S", "I", "MR", "CUSUM", "EWMA", "MA" };
const families = [_][]const u8{ "XBAR_R", "XBAR_S", "I_MR" };
const labels = [_][2][]const u8{ .{ "XBAR", "R" }, .{ "XBAR", "S" }, .{ "I", "MR" } };
const attribute_names = [_][]const u8{ "p", "np", "c", "u" };
const event_types = [_][]const u8{ "SHIFT_UP", "SHIFT_DOWN", "SPREAD_UP", "SPREAD_DOWN", "PATTERN" };
const standard: v.Limits = .{ .lcl = -3, .cl = 0, .ucl = 3 };
const Pass = struct { points: usize, limits: [2]v.Limits, out: []const usize };
const Estimate = struct { retained: []const usize, removed: []const usize, passes: []const Pass, limits: [2]v.Limits, converged: bool };
const Cusum = struct { upper: f64 = 0, lower: f64 = 0 };
const BandPoint = struct { value: f64 = 0, width: f64 = 0 };
const AttributeResult = struct { points: []const attr.Point, lines: d.Strings };
const Event = struct { first: usize, last: usize, signals: []const rules.Signal = &.{}, counts: [5]usize = @splat(0), detection: [9]usize = @splat(0), onset: usize = 0, shift: f64 = 0, spread: f64 = 0, out: usize = 0, kind: []const u8 = "" };
fn realText(value: f64) []const u8 { const text = d.fmt("{d:.4}", .{value}); return if (d.eq(text, "-0.0000")) "0.0000" else text; }
fn ruleText(rule: usize) []const u8 { return if (rule == 9) "UPPER" else if (rule == 10) "LOWER" else d.fmt("{d}", .{rule}); }
fn status(converged: bool) []const u8 { return if (converged) "converged" else "stopped"; }
fn numberList(numbers: []const usize) []const u8 { if (numbers.len == 0) return "none"; var parts: std.ArrayList([]const u8) = .empty; for (numbers) |number| d.append([]const u8, &parts, d.fmt("{d}", .{number})); return d.join(parts.items, " "); }
fn limitText(label: []const u8, l: v.Limits) []const u8 { return d.fmt("{s} lcl {s} cl {s} ucl {s}", .{ label, realText(l.lcl), realText(l.cl), realText(l.ucl) }); }
fn pairText(family: usize, limits: [2]v.Limits) []const u8 { return d.fmt("{s} {s}", .{ limitText(labels[family][0], limits[0]), limitText(labels[family][1], limits[1]) }); }
fn signalLess(_: void, a: rules.Signal, b: rules.Signal) bool { if (a.chart != b.chart) return a.chart < b.chart; if (a.last != b.last) return a.last < b.last; return a.rule < b.rule; }
fn extend(lines: *std.ArrayList([]const u8), more: d.Strings) void { for (more) |line| d.append([]const u8, lines, line); }
const Analysis = struct {
    s: d.Settings,
    values: []const i64,
    lots: []const d.Lot,
    groups: []const v.Subgroup,
    constants: d.Constants,
    estimates: [3]Estimate = undefined,
    signals: std.ArrayList(rules.Signal) = .empty,
    events: []Event = &.{},
    attributes: [4]AttributeResult = undefined,
    mu: f64 = 0,
    sigma: f64 = 0,
    reference: f64 = 0,
    threshold: f64 = 0,
    ewma_scale: f64 = 0,
    ma_scale: f64 = 0,
    cusum: []Cusum = &.{},
    ewma: []BandPoint = &.{},
    ma: []BandPoint = &.{},
    fn groupNumber(a: Analysis, signal: rules.Signal) usize { return if (signal.chart == 4 or signal.chart == 5) (signal.last - 1) / a.s.n + 1 else signal.last; }
    fn hasSignal(a: Analysis, chart: usize, last: usize, rule: usize) bool { for (a.signals.items) |signal| { if (signal.chart == chart and signal.last == last and (rule == 0 or signal.rule == rule)) return true; } return false; }
    fn eventNumber(a: Analysis, number: usize) usize { for (a.events, 1..) |event, i| { if (number >= event.first and number <= event.last) return i; } return 0; }
    fn estimateFamily(a: Analysis, family: usize) Estimate {
        const initial = d.sequence(1, if (family == 2) a.s.m * a.s.n else a.s.m);
        var retained: []const usize = initial;
        var passes: std.ArrayList(Pass) = .empty;
        var limits: [2]v.Limits = undefined;
        var converged = false;
        for (1..a.s.passes + 1) |p| {
            limits = v.familyLimits(family, retained, a.groups, a.values, a.s.n, a.constants);
            var flagged: [1001]bool = @splat(false);
            const sequences = v.familySeries(family, retained, a.groups, a.values);
            for (sequences, limits) |series, l| for (series.numbers, series.values) |number, value| { if (l.outside(value)) flagged[number] = true; };
            var out: std.ArrayList(usize) = .empty;
            for (retained) |number| { if (flagged[number]) d.append(usize, &out, number); }
            d.append(Pass, &passes, .{ .points = retained.len, .limits = limits, .out = out.items });
            if (out.items.len == 0) { converged = true; break; }
            if (p == a.s.passes) break;
            var next: std.ArrayList(usize) = .empty;
            for (retained) |number| { if (!flagged[number]) d.append(usize, &next, number); }
            retained = next.items;
        }
        var removed: std.ArrayList(usize) = .empty;
        for (initial) |number| { if (!d.contains(retained, number)) d.append(usize, &removed, number); }
        return .{ .retained = retained, .removed = removed.items, .passes = passes.items, .limits = limits, .converged = converged };
    }
    fn chartLimits(a: Analysis, chart: usize) v.Limits { return a.estimates[chart / 2].limits[chart % 2]; }
    fn phase2Series(a: Analysis, chart: usize) v.Series {
        const numbers = d.sequence(if (chart >= 4) a.s.m * a.s.n + 1 else a.s.m + 1, if (chart >= 4) a.values.len else a.groups.len);
        const values = d.alloc(f64, numbers.len);
        for (numbers, values) |number, *value| {
            value.* = switch (chart) { 0, 2 => a.groups[number - 1].mean, 1 => d.real(a.groups[number - 1].range), 3 => a.groups[number - 1].sd, 4 => d.real(a.values[number - 1]), else => d.real(@abs(a.values[number - 1] - a.values[number - 2])) };
        }
        return .{ .numbers = numbers, .values = values };
    }
    fn addBandSignal(a: *Analysis, chart: usize, point: BandPoint, first: usize, last: usize) void {
        const up = point.value > a.mu + point.width;
        if (up or point.value < a.mu - point.width) d.append(rules.Signal, &a.signals, .{ .chart = chart, .rule = if (up) 9 else 10, .first = first, .last = last, .value = point.value, .direction = if (up) .UP else .DOWN });
    }
    fn monitor(a: *Analysis) void {
        for (0..6) |chart| for (rules.check(chart, a.phase2Series(chart), a.chartLimits(chart), a.s.rules[chart])) |signal| d.append(rules.Signal, &a.signals, signal);
        a.mu = a.estimates[0].limits[0].cl;
        a.sigma = a.estimates[0].limits[1].cl / a.constants.d2 / @sqrt(d.real(a.s.n));
        a.reference = a.s.k * a.sigma; a.threshold = a.s.h * a.sigma;
        const decay = (1 - a.s.lambda) * (1 - a.s.lambda); const rho = a.s.lambda / (2 - a.s.lambda);
        a.ewma_scale = a.s.e * a.sigma * @sqrt(rho); a.ma_scale = 3 * a.sigma / @sqrt(d.real(a.s.span));
        a.cusum = d.alloc(Cusum, a.groups.len); @memset(a.cusum, .{});
        a.ewma = d.alloc(BandPoint, a.groups.len); @memset(a.ewma, .{});
        a.ma = d.alloc(BandPoint, a.groups.len); @memset(a.ma, .{});
        var upper: f64 = 0; var lower: f64 = 0; var uprun: usize = 0; var downrun: usize = 0; var smoothed = a.mu; var factor: f64 = 1;
        for (a.groups[a.s.m..]) |group| {
            const i = group.number; const index = i - 1;
            upper = @max(0, upper + (group.mean - a.mu - a.reference)); lower = @max(0, lower + (a.mu - group.mean - a.reference));
            uprun = if (upper > 0) uprun + 1 else 0; downrun = if (lower > 0) downrun + 1 else 0;
            a.cusum[index] = .{ .upper = upper, .lower = lower };
            if (upper > a.threshold) { d.append(rules.Signal, &a.signals, .{ .chart = 6, .rule = 9, .first = i - uprun + 1, .last = i, .value = upper, .direction = .UP }); upper = 0; uprun = 0; }
            if (lower > a.threshold) { d.append(rules.Signal, &a.signals, .{ .chart = 6, .rule = 10, .first = i - downrun + 1, .last = i, .value = lower, .direction = .DOWN }); lower = 0; downrun = 0; }
            smoothed = a.s.lambda * group.mean + (1 - a.s.lambda) * smoothed; factor *= decay;
            a.ewma[index] = .{ .value = smoothed, .width = a.s.e * a.sigma * @sqrt(rho * (1 - factor)) };
            const first = @max(a.s.m + 1, if (i >= a.s.span) i - a.s.span + 1 else 1); const count = i - first + 1;
            var total: i64 = 0; for (a.groups[first - 1..i]) |g| total += g.total;
            a.ma[index] = .{ .value = d.real(total) / d.real(a.s.n * count), .width = 3 * a.sigma / @sqrt(d.real(count)) };
            a.addBandSignal(7, a.ewma[index], i, i); a.addBandSignal(8, a.ma[index], first, i);
        }
        std.mem.sort(rules.Signal, a.signals.items, {}, signalLess);
    }
    fn buildEvents(a: *Analysis) void {
        var marked: [101]bool = @splat(false); for (a.signals.items) |signal| marked[a.groupNumber(signal)] = true;
        var events: std.ArrayList(Event) = .empty;
        for (1..a.groups.len + 1) |i| {
            if (!marked[i]) continue;
            if (events.items.len > 0 and i - events.items[events.items.len - 1].last - 1 <= a.s.gap) events.items[events.items.len - 1].last = i else d.append(Event, &events, .{ .first = i, .last = i });
        }
        for (events.items) |*event| {
            var selected: std.ArrayList(rules.Signal) = .empty;
            for (a.signals.items) |signal| {
                const g = a.groupNumber(signal); if (g < event.first or g > event.last) continue;
                d.append(rules.Signal, &selected, signal);
                const spread = signal.chart == 1 or signal.chart == 3 or signal.chart == 5;
                const bucket: usize = if (signal.direction == .NONE) 4 else if (spread) (if (signal.direction == .UP) @as(usize, 2) else 3) else (if (signal.direction == .UP) @as(usize, 0) else 1);
                event.counts[bucket] += 1;
                if (event.detection[signal.chart] == 0 or g < event.detection[signal.chart]) event.detection[signal.chart] = g;
                if (signal.chart == 6 and (event.onset == 0 or signal.first < event.onset)) event.onset = signal.first;
            }
            event.signals = selected.items; if (event.onset == 0) event.onset = event.first;
            var best: usize = 0; for (1..5) |i| { if (event.counts[i] > event.counts[best]) best = i; } event.kind = event_types[best];
            var total: i64 = 0; var deviations: f64 = 0;
            for (a.groups[event.first - 1..event.last]) |group| { total += group.total; deviations += group.sd; for (group.values) |value| { if (value < a.s.lsl or value > a.s.usl) event.out += 1; } }
            const count = event.last - event.first + 1;
