const v = @import("variable_charts.zig");
fn place(band: *[61]u8, position: f64, symbol: u8) void { band[@intFromFloat(@min(60, @max(0, position)))] = symbol; }
fn framed(center: f64) [61]u8 { var band: [61]u8 = @splat('.'); place(&band, 0, ':'); place(&band, 60, ':'); place(&band, center, '|'); return band; }
pub fn limitsBand(l: v.Limits, value: f64, signalled: bool) [61]u8 { const span = l.ucl - l.lcl; var band = framed(@floor(60 * ((l.cl - l.lcl) / span) + 0.5)); place(&band, @floor(60 * ((value - l.lcl) / span) + 0.5), if (signalled) '*' else 'o'); return band; }
pub fn cusumBand(upper: f64, lower: f64, threshold: f64, up: bool, down: bool) [61]u8 { var band = framed(30); if (lower > 0) place(&band, 30 - @min(30, @floor(30 * (lower / threshold) + 0.5)), if (down) '*' else '-'); if (upper > 0) place(&band, 30 + @min(30, @floor(30 * (upper / threshold) + 0.5)), if (up) '*' else '+'); return band; }
pub fn widthBand(scale: f64, width: f64, value: f64, center: f64, signalled: bool) [61]u8 { var band: [61]u8 = @splat('.'); const edge = @min(30, @floor(30 * (width / scale) + 0.5)); place(&band, 30, '|'); place(&band, 30 - edge, ':'); place(&band, 30 + edge, ':'); place(&band, 30 + @floor(30 * ((value - center) / scale) + 0.5), if (signalled) '*' else 'o'); return band; }
pub fn standardBand(z: f64, ok: bool) [61]u8 { var band = framed(30); place(&band, 30 + @floor(10 * z + 0.5), if (ok) 'o' else '*'); return band; }

const std = @import("std");
const d = @import("dataset.zig");
const v = @import("variable_charts.zig");
pub const Direction = enum { UP, DOWN, NONE };
pub const Signal = struct { chart: usize, rule: usize, first: usize, last: usize, value: f64, direction: Direction };
pub const Zones = struct { lcl: f64, cl: f64, ucl: f64, u1: f64, u2: f64, l1: f64, l2: f64 };
pub fn zones(l: v.Limits) Zones { const a = (l.ucl - l.cl) / 3; const b = (l.cl - l.lcl) / 3; return .{ .lcl = l.lcl, .cl = l.cl, .ucl = l.ucl, .u1 = l.cl + a, .u2 = l.cl + 2 * a, .l1 = l.cl - b, .l2 = l.cl - 2 * b }; }
pub fn zoneName(l: v.Limits, value: f64) []const u8 { const z = zones(l); return if (value > z.ucl) "OUT+" else if (value < z.lcl) "OUT-" else if (value > z.u2) "A+" else if (value > z.u1) "B+" else if (value > z.cl) "C+" else if (value < z.l2) "A-" else if (value < z.l1) "B-" else if (value < z.cl) "C-" else "C0"; }
fn direction(rule: usize, window: []const f64, z: Zones) ?Direction {
    const last = window[window.len - 1];
    switch (rule) {
        1 => { if (last > z.ucl or last < z.lcl) return if (last > z.cl) .UP else .DOWN; },
        2, 3 => { const upper = if (rule == 2) z.u2 else z.u1; const lower = if (rule == 2) z.l2 else z.l1; const needed: usize = if (rule == 2) 2 else 4; var up: usize = 0; var down: usize = 0; for (window) |value| { if (value > upper) up += 1; if (value < lower) down += 1; } if (last > upper and up >= needed) return .UP; if (last < lower and down >= needed) return .DOWN; },
        4 => { var up = true; var down = true; for (window) |value| { up = up and value > z.cl; down = down and value < z.cl; } if (up) return .UP; if (down) return .DOWN; },
        5 => { var up = true; var down = true; for (1..window.len) |i| { up = up and window[i] > window[i - 1]; down = down and window[i] < window[i - 1]; } if (up) return .UP; if (down) return .DOWN; },
        6 => { var previous: f64 = 0; for (1..window.len) |i| { const delta = window[i] - window[i - 1]; if (delta == 0 or (i > 1 and (delta > 0) == (previous > 0))) return null; previous = delta; } return .NONE; },
        7 => { for (window) |value| { if (!(value > z.l1 and value < z.u1)) return null; } return .NONE; },
        8 => { var up = false; var down = false; for (window) |value| { if (value > z.u1) up = true else if (value < z.l1) down = true else return null; } if (up and down) return .NONE; },
        else => unreachable,
    }
    return null;
}
pub fn check(chart: usize, series: v.Series, limits: v.Limits, rules: []const usize) []const Signal {
    const lengths = [_]usize{ 1, 3, 5, 8, 6, 14, 15, 8 };
    const z = zones(limits);
    var signals: std.ArrayList(Signal) = .empty;
    for (series.values, 0..) |value, i| for (rules) |rule| { const length = lengths[rule - 1]; if (i + 1 < length) continue; const first = i + 1 - length; if (direction(rule, series.values[first..i + 1], z)) |side| d.append(Signal, &signals, .{ .chart = chart, .rule = rule, .first = series.numbers[first], .last = series.numbers[i], .value = value, .direction = side }); };
    return signals.items;
}

const d = @import("dataset.zig");
pub const Subgroup = struct { number: usize, values: []const i64, total: i64, squares: i64, mean: f64, range: i64, sd: f64 };
pub const Limits = struct { lcl: f64, cl: f64, ucl: f64, pub fn outside(l: Limits, value: f64) bool { return value > l.ucl or value < l.lcl; } };
pub const Series = struct { numbers: []const usize, values: []const f64 };
pub fn statistics(values: []const i64, size: usize) []const Subgroup {
    const groups = d.alloc(Subgroup, values.len / size);
    const n: i64 = @intCast(size);
    for (groups, 0..) |*group, i| {
        const chosen = values[i * size..][0..size];
        var total: i64 = 0; var squares: i64 = 0; var low = chosen[0]; var high = chosen[0];
        for (chosen) |value| { total += value; squares += value * value; low = @min(low, value); high = @max(high, value); }
        group.* = .{ .number = i + 1, .values = chosen, .total = total, .squares = squares, .mean = d.real(total) / d.real(n), .range = high - low, .sd = @sqrt(d.real(n * squares - total * total) / d.real(n * (n - 1))) };
    }
    return groups;
}
pub fn familyLimits(family: usize, numbers: []const usize, groups: []const Subgroup, values: []const i64, n: usize, c: d.Constants) [2]Limits {
    var total: i64 = 0; var ranges: i64 = 0; var deviations: f64 = 0;
    if (family == 2) {
        for (numbers, 0..) |number, i| { total += values[number - 1]; if (i > 0) ranges += @intCast(@abs(values[number - 1] - values[numbers[i - 1] - 1])); }
        const mean = d.real(total) / d.real(numbers.len);
        const rbar = d.real(ranges) / d.real(numbers.len - 1);
        const width = 3 * rbar / 1.128;
        return .{ .{ .lcl = mean - width, .cl = mean, .ucl = mean + width }, .{ .lcl = 0, .cl = rbar, .ucl = 3.267 * rbar } };
    }
    for (numbers) |number| { const g = groups[number - 1]; total += g.total; ranges += g.range; deviations += g.sd; }
    const mean = d.real(total) / d.real(numbers.len * n);
    const spread = if (family == 0) d.real(ranges) / d.real(numbers.len) else deviations / d.real(numbers.len);
    const width = (if (family == 0) c.a2 else c.a3) * spread;
    return .{ .{ .lcl = mean - width, .cl = mean, .ucl = mean + width }, .{ .lcl = (if (family == 0) c.d3 else c.b3) * spread, .cl = spread, .ucl = (if (family == 0) c.d4 else c.b4) * spread } };
}
pub fn familySeries(family: usize, numbers: []const usize, groups: []const Subgroup, values: []const i64) [2]Series {
    const first = d.alloc(f64, numbers.len);
    const second = d.alloc(f64, if (family == 2) numbers.len - 1 else numbers.len);
    for (numbers, 0..) |number, i| {
        if (family == 2) { first[i] = d.real(values[number - 1]); if (i > 0) second[i - 1] = d.real(@abs(values[number - 1] - values[numbers[i - 1] - 1])); }
        else { const g = groups[number - 1]; first[i] = g.mean; second[i] = if (family == 0) d.real(g.range) else g.sd; }
    }
    return .{ .{ .numbers = numbers, .values = first }, .{ .numbers = if (family == 2) numbers[1..] else numbers, .values = second } };
}
